#include <bits/stdc++.h>
using namespace std;

#define ll long long

int main() {
	// your code goes here
   
    int t;
    cin>>t;
    
    while(t--){
        int n;
        cin>>n;
        
        int ttl=3*n;
        
        vector<ll>a(ttl);
        
        for(int i=0;i<ttl;i++){
            cin>>a[i];
        }
        sort(a.rbegin(),a.rend());
        
        vector<ll>pref(ttl+1,0);
        
        for(int i=0;i<ttl;i++){
            pref[i+1]=pref[i]+a[i];
        }
        ll ans=0;
        
        for(int x=0;x<=n;x++){
            int mt=n-x;
            
            int l=0;
            int r=mt;
            
            
            
            while(l<r){
                int m=(l+r+1)/2;
                int p=x+2*(m-1);
                
                
                int f=ttl-2*x-(m-1);
                ll c=a[p]+a[p+1]-3ll * a[f-1];
                
                if(c>=0){
                    l=m;
                }else{
                    r=m-1;
                }
            }
            int _2 = l;
            int _3 =n-x-_2;
            
            int p=x;
            int q=x+ 2*_2;
            int s=q+3*_3;
            
            
            ll ct =0;
            
            ct+=6ll*pref[p];
            ct+=4ll*(pref[q]-pref[p]);
            
            
            
    ct+=3ll*(pref[s]-pref[q]);
      ans=max(ans,ct);
             
        }
        
        cout<<ans<<endl;
        
    }
    return 0;
}
